/**
 * Unit tests for UserProfileController using JUnit 5 and Mockito.
 * Tests cover happy paths, validation, and error scenarios.
 */
@ExtendWith(MockitoExtension.class)
@WebMvcTest(UserProfileController.class)
class UserProfileControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService;

    @MockBean
    private UserMapper userMapper;

    @Test
    void getUser_shouldReturnUserWhenExists() throws Exception {
        // Given
        Long userId = 1L;
        User user = new User(userId, "test@example.com", "password123", "Test User");
        UserDTO userDTO = new UserDTO(userId, "test@example.com", "Test User");

        given(userService.findById(userId)).willReturn(Optional.of(user));
        given(userMapper.toDto(user)).willReturn(userDTO);

        // When & Then
        mockMvc.perform(get("/api/users/{id}", userId))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(userId))
            .andExpect(jsonPath("$.email").value("test@example.com"));
    }

    @Test
    void createUser_shouldReturnCreatedUser() throws Exception {
        // Given
        UserCreateRequest request = new UserCreateRequest("new@example.com", "password123", "New User");
        User user = new User(2L, "new@example.com", "password123", "New User");
        UserDTO userDTO = new UserDTO(2L, "new@example.com", "New User");

        given(userMapper.toEntity(request)).willReturn(user);
        given(userService.save(user)).willReturn(user);
        given(userMapper.toDto(user)).willReturn(userDTO);

        // When & Then
        mockMvc.perform(post("/api/users")
                .contentType(MediaType.APPLICATION_JSON)
                .content(asJsonString(request)))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id").value(2L));
    }

    private static String asJsonString(final Object obj) {
        try {
            return new ObjectMapper().writeValueAsString(obj);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
